37:   :m_data_chunk(NULL),m_data_size_padded(0) {
38:     // Try to open the specified file for reading.
39:     ifstream file(name.c_str(),ios::binary);
40:     if (!file) {
41:         m_last_error_msg="Unable to open file \""+name+"\" for reading.";
42:         return;
43:     }
