77:     // Encryption for the "random" Initialization Vector.
78:     typedef ECB_Mode<CIPHER>::Encryption IVEncryption;
79: 
80:     // Encryption for the (hashed and padded) password.
81:     typedef CBC_Mode<CIPHER>::Encryption PWEncryption;
82: 
83:     // Calculate the password's 20-byte SHA-1 hash and pad to 32 bytes.
84:     byte digest[sizeof(m_password_hash)];
85:     memset(digest,0xff,sizeof(digest));
86:     SHA().CalculateDigest(
87:         digest,
88:         reinterpret_cast<const byte*>(password.c_str()),
89:         static_cast<unsigned int>(password.length())
90:     );
91: 
92:     // Clamp the key length to its allowed maximum.
93:     unsigned int key_length=OI_MIN_2(
94:         static_cast<unsigned int>(sizeof(digest)),
95:         static_cast<unsigned int>(CIPHER::MAX_KEYLENGTH)
96:     );
97: 
98:     // Generate a "random" IV like DCPcrypt does.
99:     byte iv[CIPHER::BLOCKSIZE];
100:     memset(iv,0xff,sizeof(iv));
101:     IVEncryption *enc_iv=new IVEncryption(digest,key_length);
102:     enc_iv->ProcessData(iv,iv,sizeof(iv));
103:     delete enc_iv;
104: 
105:     // Initialize the decryption incl. encryption needed for padding.
106:     CBC_Mode<CIPHER>::Decryption dec_data(digest,key_length,iv);
107:     CIPHER::Encryption enc_pad(digest,key_length);
108: 
109:     // Encrypt the padded password's SHA-1 hash.
110:     PWEncryption *enc_digest=new PWEncryption(digest,key_length,iv);
111:     enc_digest->ProcessData(digest,digest,sizeof(digest));
112:     delete enc_digest;
