115:     unsigned int *a=(unsigned int*)m_password_hash;
116:     unsigned int *b=(unsigned int*)digest;
117:     for (unsigned int i=0;i<sizeof(m_password_hash)/sizeof(unsigned int);++i) {
118:         if (*a!=*b) {
119:             m_last_error_msg="The specified password is invalid.";
120:             return NULL;
121:         }
122:         ++a;
123:         ++b;
124:     }
125: 
126:     // For data chunks not evenly divisible by the cipher's block size some
