34: OublietteFile::OublietteFile(string const& name)
35: :   m_data_chunk(NULL)
36: ,   m_data_size_padded(0)
37: {
38:     // Try to open the specified file for reading.
39:     ifstream file(name.c_str(),ios::binary);
40:     if (!file) {
41:         m_last_error_msg="Unable to open file \""+name+"\" for reading.";
42:         return;
43:     }
44: 
45:     // Read the unencrypted plain text header.
46:     file.read(reinterpret_cast<char*>(&m_plain_header),sizeof(m_plain_header));
47: 
48:     // Check for plausibility.
49:     if (!m_plain_header.isValid()) {
50:         m_last_error_msg="The file header is invalid or corrupted.";
51:         return;
52:     }
53: 
54:     // Read the encrypted password's SHA-1 hash.
55:     file.read(reinterpret_cast<char*>(m_password_hash),sizeof(m_password_hash));
56: 
57:     // Compare the remaining file size to what is stated in the header.
58:     ifstream::pos_type pos=file.tellg();
59:     file.seekg(0,ios::end);
60:     if (static_cast<unsigned long>(file.tellg()-pos)!=m_plain_header.getDataSize()) {
61:         m_last_error_msg="The file size is invalid.";
62:         return;
63:     }
64:     file.seekg(pos,ios::beg);
65: 
66:     // Read the encrypted data; always allocate a multiple of 8 bytes (the block
67:     // size of Blowfish and IDEA).
68:     m_data_size_padded=(m_plain_header.getDataSize()+7)&(~7);
69:     m_data_chunk=new char[m_data_size_padded];
70:     file.read(m_data_chunk,m_plain_header.getDataSize());
71: }
