73: template<typename CIPHER>
74: OublietteFile::CipherTextHeader const* OublietteFile::decrypt(string const& password)
75: {
76:     using namespace CryptoPP;
77: 
78:     // Encryption for the "random" Initialization Vector.
79:     typedef ECB_Mode<CIPHER>::Encryption IVEncryption;
80: 
81:     // Encryption for the (hashed and padded) password.
82:     typedef CBC_Mode<CIPHER>::Encryption PWEncryption;
83: 
84:     // Calculate the password's 20-byte SHA-1 hash and pad to 32 bytes.
85:     byte digest[sizeof(m_password_hash)];
86:     memset(digest,0xff,sizeof(digest));
87:     SHA().CalculateDigest(
88:         digest,
89:         reinterpret_cast<byte const*>(password.c_str()),
90:         static_cast<unsigned int>(password.length())
91:     );
92: 
93:     // Clamp the key length to its allowed maximum.
94:     unsigned int key_length=min(
95:         static_cast<unsigned int>(sizeof(digest)),
96:         static_cast<unsigned int>(CIPHER::MAX_KEYLENGTH)
97:     );
98: 
99:     // Generate a "random" IV like DCPcrypt does.
100:     byte iv[CIPHER::BLOCKSIZE];
101:     memset(iv,0xff,sizeof(iv));
102:     IVEncryption *enc_iv=new IVEncryption(digest,key_length);
103:     enc_iv->ProcessData(iv,iv,sizeof(iv));
104:     delete enc_iv;
105: 
106:     // Initialize the decryption incl. encryption needed for padding.
107:     CBC_Mode<CIPHER>::Decryption dec_data(digest,key_length,iv);
108:     CIPHER::Encryption enc_pad(digest,key_length);
109: 
110:     // Encrypt the padded password's SHA-1 hash.
111:     PWEncryption *enc_digest=new PWEncryption(digest,key_length,iv);
112:     enc_digest->ProcessData(digest,digest,sizeof(digest));
113:     delete enc_digest;
